// src/frontend/ui-registry.ts
function buildCatalog(packs) {
  const panels = new Map;
  const editors = new Map;
  const configs = new Map;
  const chips = new Map;
  const previews = new Map;
  const gmSections = new Map;
  const fields = new Map;
  const placeFields = new Map;
  const sheets2 = new Map;
  const glances = new Map;
  const orgTabs2 = new Map;
  const ids = new Set;
  for (const pack of packs) {
    if (ids.has(pack.id))
      throw new Error(`UI pack ${pack.id} is registered twice`);
    ids.add(pack.id);
    const registry = {
      panel(def2) {
        if (panels.has(def2.id))
          throw new Error(`Panel ${def2.id} (pack ${pack.id}) is already registered`);
        panels.set(def2.id, def2);
      },
      editor(def2) {
        if (editors.has(def2.collection))
          throw new Error(`An editor for ${def2.collection} (pack ${pack.id}) is already registered`);
        editors.set(def2.collection, def2);
      },
      config(component) {
        if (configs.has(pack.id))
          throw new Error(`Config fields for pack ${pack.id} are already registered`);
        configs.set(pack.id, component);
      },
      chip(kind, component) {
        if (chips.has(kind))
          throw new Error(`A chip renderer for ${kind} (pack ${pack.id}) is already registered`);
        chips.set(kind, component);
      },
      preview(collection, component) {
        if (previews.has(collection))
          throw new Error(`A preview for ${collection} (pack ${pack.id}) is already registered`);
        previews.set(collection, component);
      },
      gm(def2) {
        if (gmSections.has(def2.id))
          throw new Error(`A GM view tab ${def2.id} (pack ${pack.id}) is already registered`);
        gmSections.set(def2.id, def2);
      },
      field(def2) {
        const key = `${def2.kind}.${def2.field}`;
        if (fields.has(key))
          throw new Error(`An editor for the field ${key} (pack ${pack.id}) is already registered`);
        fields.set(key, def2);
      },
      placeField(def2) {
        if (placeFields.has(def2.field))
          throw new Error(`An editor for the place field ${def2.field} (pack ${pack.id}) is already registered`);
        placeFields.set(def2.field, def2);
      },
      sheet(kind, component) {
        if (sheets2.has(kind))
          throw new Error(`A sheet for ${kind} (pack ${pack.id}) is already registered`);
        sheets2.set(kind, component);
      },
      glance(def2) {
        if (glances.has(def2.id))
          throw new Error(`Glance ${def2.id} (pack ${pack.id}) is already registered`);
        glances.set(def2.id, def2);
      },
      orgTab(def2) {
        if (orgTabs2.has(def2.id))
          throw new Error(`An organization tab ${def2.id} (pack ${pack.id}) is already registered`);
        orgTabs2.set(def2.id, def2);
      }
    };
    pack.register(registry);
  }
  return {
    panels: [...panels.values()].sort((a3, b3) => a3.order - b3.order || a3.id.localeCompare(b3.id)),
    editors,
    configs,
    chips,
    previews,
    gmSections: [...gmSections.values()].sort((a3, b3) => a3.order - b3.order || a3.id.localeCompare(b3.id)),
    fields: [...fields.values()],
    placeFields: [...placeFields.values()],
    sheets: sheets2,
    glances: [...glances.values()].sort((a3, b3) => a3.order - b3.order || a3.id.localeCompare(b3.id)),
    orgTabs: [...orgTabs2.values()].sort((a3, b3) => a3.order - b3.order || a3.id.localeCompare(b3.id)),
    packs: [...ids]
  };
}

